-- Daily challenges for 2026-11-18: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-18. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('facing-small-fears', 'Facing Small Fears', 'For anyone who lets small fears make their world a little smaller. Each day is one gentle, manageable step toward something that feels a bit scary, taken at your own pace and with kindness.', 'Anxiety', 365, array['Anxiety', 'Motivation', 'Self-Compassion']::text[], 1, '2026-11-18T17:00:00+00:00'::timestamptz),
  ('caring-for-the-things-you-own', 'Caring for the Things You Own', 'For anyone who wants the things they already have to last and feel good to use. Each day is one small way to clean, mend, store or look after your belongings, so they serve you well for longer.', 'Home', 365, array['Habits', 'Values']::text[], 1, '2026-11-18T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('facing-small-fears', 'caring-for-the-things-you-own');

